import {articleMarkup} from './article-page.js';
import {contextualText} from './contextual-popovers.js';
import {detailSummaryMarkup,summaryParts} from './summary-stream.js';
import {oklchChannels} from './surface-colors.js';
import {contentBlocks} from './content-blocks.js';
import {escapeText,headingText,safeHref} from './content/html.js';
import {imageMarkup} from './media-loading.js';
import {detailCaptionLines,detailCaptionInner,detailCaptionDataAttributes} from './detail-caption.js';
import {backdropSources} from './backdrop-sources.js';
import {aboutBodyMarkup} from './about-page.js';
import {aboutLabMarkup,cardWorldPageMarkup} from './about-lab.js';
// The same card projection renders in the grid, content references and AI results.
function cardColorTokens(p){
 const colors=String(p.bg||'').match(/#[0-9a-f]{6}/gi)||[];
 const first=oklchChannels(colors[0]),last=oklchChannels(colors.at(-1));
 const hue=color=>color?color[2].toFixed(2):'0';
 // An authored ambient pair is the manual override; it wins over sampled image colour.
 const ambient=(p.ambient||[]).map(oklchChannels),manual=ambient.length===2&&ambient.every(Boolean)?`;--ambient-manual-start:${hue(ambient[0])};--ambient-manual-end:${hue(ambient[1])}`:'';
 return `--project-hue-start:${hue(first)};--project-hue-end:${hue(last)};--project-chroma-scale:${first&&first[1]>.001?1:0};--card-title-ink:var(--ink)${manual}`;
}
// Featured stage backdrop. Always in the markup but only displayed (and so only fetched) when the
// Home "Featured stage" setting shows it; the media loader never loads hidden images.
function cardBackdrop(p){const source=backdropSources(p.background);return source?`<div class="card-backdrop"><img alt="" decoding="async" data-media-pending data-media-src="${escapeText(source.src)}" data-media-srcset="${escapeText(source.srcset)}" data-media-sizes="100vw"></div>`:'';}
// Card details (Settings → Cards): status pill above the client, discipline tags under the results line.
const statusMarkup=p=>p.projectStatus?`<span class="card-status" data-status="${escapeText(p.projectStatus.toLowerCase().replace(/&/g,'and'))}">${escapeText(p.projectStatus)}</span>`:'';
const tagsMarkup=p=>p.disciplines?.length?`<p class="card-tags text-eyebrow">${p.disciplines.map(tag=>`<span>${escapeText(tag)}</span>`).join('')}</p>`:'';
// Note cards (a project's homeCards): a roomy card with a smaller media item inside and an optional title and
// description. Always in the markup, shown by CSS only in Featured stage mode, so hidden media is never fetched.
const noteMedia=media=>!media?'':media.type==='video'?`<video class="note-card-video" muted loop playsinline autoplay preload="none" data-media-src="${safeHref(media.url,{asset:true})}" aria-hidden="true"></video>`:imageMarkup(media.url,media.alt);
const noteCaption=card=>card.title||card.description?`<figcaption>${card.title?`<h3 class="note-card-title">${escapeText(card.title)}</h3>`:''}${card.description?`<p class="note-card-description">${escapeText(card.description)}</p>`:''}</figcaption>`:'';
const notesMarkup=p=>p.homeCards?.length?`<div class="card-notes" data-count="${p.homeCards.length}">${p.homeCards.map(card=>`<figure class="note-card"><div class="note-card-media">${noteMedia(card.media)}</div>${noteCaption(card)}</figure>`).join('')}</div>`:'';
function labMark(p){return p.projectKind==='lab'?'<span class="card-lab-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 3h6M10 3v7L4.8 18.3A1.8 1.8 0 0 0 6.3 21h11.4a1.8 1.8 0 0 0 1.5-2.7L14 10V3M8 15h8"/></svg></span>':'';}
function visual(p,eager=false){if(!p.image&&!p.videoUrl)return '';return `<div class="visual">${p.image?imageMarkup(p.image,p.imageAlt||`Product design screen for ${p.name}`,{eager}):''}${p.videoUrl?`<video class="project-video" data-video-url="${safeHref(p.videoUrl,{asset:true})}" muted playsinline preload="none" aria-hidden="true"></video>`:''}</div>`;}
function qrCodeMarkup(p){if(!p.qrCodeUrl)return '';return `<figure class="detail-project-qr"><img src="${safeHref(p.qrCodeUrl,{asset:true})}" alt="${escapeText(p.qrCodeAlt||`QR code for ${p.name}`)}" loading="lazy" decoding="async">${p.qrCodeLabel?`<figcaption>${escapeText(p.qrCodeLabel)}</figcaption>`:''}</figure>`;}
export function streamWords(value,start=0){return (String(value||'').match(/\S+\s*/g)||[]).map((word,index)=>`<span data-card-copy-word style="--card-copy-word-index:${start+index}">${escapeText(word).replace(/\r?\n/g,'<br>')}</span>`).join('');}
const start=(p,options,classes,attributes='')=>`<${options.link?'a':'button'} class="surface project-card ${classes}" data-hover-effect="reveal" style="--project-bg:${escapeText(p.bg)};${cardColorTokens(p)}" ${options.link?`href="#${escapeText(p.documentId||p.id)}" data-content-card="${escapeText(p.documentId||p.id)}"`:`data-card="${escapeText(p.id)}"`} ${attributes} aria-label="Open ${escapeText(p.name)}${p.projectKind==='lab'?' — Lab project':''}">`;
export function card(p,i,layout='masonry',options={}){
 if(p.body)return informationCard(p,options);
 const lead=summaryParts(p).lead;
 // The client also leads the title when the dev setting puts it inline; CSS shows one or the other.
 const inlineClient=p.client?`${p.client}. `:'',clientWords=(inlineClient.match(/\S+\s*/g)||[]).length,titleWords=clientWords+(String(p.title||'').match(/\S+\s*/g)||[]).length;
 return start(p,options,`image-card ${!p.image&&!p.videoUrl?'text-only-card ':''}${p.cardAspect==='portrait'?'portrait':''}`,`data-card-layout="${escapeText(layout)}" data-card-orientation="${escapeText(p.cardAspect||'landscape')}" data-featured="${p.featured===true}"`)+`${cardBackdrop(p)}${labMark(p)}<div class="card-copy">${statusMarkup(p)}${p.client?`<p class="card-client">${escapeText(p.client)}</p>`:''}<h3>${inlineClient?`<span class="card-title-client">${streamWords(inlineClient)}</span>`:''}<span class="card-title-text" data-source="title" data-title="${escapeText(p.title||'')}" data-category="${escapeText(p.shortCategory||p.name||'')}" data-offset="${clientWords}">${streamWords(p.title,clientWords)}</span></h3>${lead?`<p class="project-summary" data-source="summary" data-summary="${escapeText(lead)}" data-company-year="${escapeText([p.client,p.year].filter(Boolean).join(' · '))}" data-offset="${titleWords+2}">${streamWords(lead,titleWords+2)}</p>`:''}${tagsMarkup(p)}</div>${visual(p)}${notesMarkup(p)}</${options.link?'a':'button'}>`;
}
function mediaActions(p){return `<div class="detail-media-actions">${p.prototype?.url?'<button type="button" data-media-focus="prototype">View prototype</button>':''}${p.watchPrototype?.url?`<button type="button" data-media-focus="watch-prototype">${escapeText(p.watchPrototype.label||'Watch prototype')}</button>`:''}<button type="button" data-media-focus="fullscreen" aria-label="View full screen" data-tooltip="View full screen" hidden><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg></button></div>`;}
// With "Details title beside image" on, a card-style caption leads the page and the image runs full width under it; the
// long title, summary and facts follow in a text column. The caption is always rendered so the setting can switch live.
function detailCaption(p){const data={client:String(p.client||p.name||'').split(' • ')[0],title:p.title,category:p.shortCategory||p.name,summary:summaryParts(p).lead,year:p.year,intro:p.intro||''},lines=detailCaptionLines(data);return data.title||data.summary||data.client?`<div class="detail-caption" ${detailCaptionDataAttributes(data)}>${detailCaptionInner(lines)}</div>`:'';}
function detail(p,layout,{headingBesideImage=false}={}){const hasMedia=Boolean(p.image||p.videoUrl);return `<section class="surface detail${headingBesideImage&&hasMedia?' heading-beside-image':''}${hasMedia?'':' text-only-detail'}" style="--project-bg:${escapeText(p.bg)};${cardColorTokens(p)}" data-card-layout="${escapeText(layout)}" data-card-orientation="${escapeText(p.cardAspect||'landscape')}" data-surface>${hasMedia?detailCaption(p):''}${p.client?`<p class="project-client">${escapeText(p.client)}</p>`:''}<h1 tabindex="-1">${headingText(p.intro||p.pageTitle||p.title)}</h1>${detailSummaryMarkup(p)}<div class="detail-layout">${hasMedia?`<div class="detail-media-column">${visual(p,true)}${qrCodeMarkup(p)}${mediaActions(p)}</div>`:''}<div class="description"><dl>${[['Context',p.context],['Challenge',p.challenge],['My role',p.role],['Key work',p.work],['Impact',p.impact||p.results],['What happened after',p.aftermath],['What it taught me',p.lesson]].filter(([,value])=>value).map(([label,value])=>`<div class="detail-fact" data-detail-fact><dt class="text-eyebrow">${escapeText(label)}</dt><dd>${escapeText(value).replace(/\r?\n/g,'<br>')}</dd></div>`).join('')}</dl></div></div></section>`;}
function informationCard(p,options={}){return start(p,options,'info-card')+`<h2>${headingText(p.title)}</h2><p class="eyebrow">${escapeText(p.category)}</p><p class="info-summary">${escapeText(p.body[0])}</p></${options.link?'a':'button'}>`;}
export function cardDetail(p,layout='regular',options={}){if(!p.body)return detail(p,layout,options);if(p._article)return articleMarkup(p);if(p.id==='about-lab')return aboutLabMarkup(p);if(p.id==='about-infinite')return cardWorldPageMarkup(p,'infinite');if(p.id==='about-sphere')return cardWorldPageMarkup(p,'sphere');if(p.id==='about')return `<section class="surface detail info-detail about-detail" style="--project-bg:${escapeText(p.bg)};${cardColorTokens(p)}" data-surface>${aboutBodyMarkup(p)}</section>`;return `<section class="surface detail info-detail" style="--project-bg:${escapeText(p.bg)};${cardColorTokens(p)}" data-info-page="${escapeText(p.id)}" data-surface><h1 tabindex="-1">${headingText(p.title)}</h1><div class="info-body">${p.body.map((text,i)=>`<p${i===0?' class="info-summary"':''}>${contextualText(text)}</p>`).join('')}${p.link?`<a href="${safeHref(p.link.url)}" target="_blank" rel="noopener">${escapeText(p.link.label)}</a>`:''}</div></section>${p.blocks?.length?contentBlocks(p.blocks,p.contentColumns):''}`;}
